mapper.select:
SELECT document_id, sharing_revision AS revision, lifecycle, published_version FROM knowledge_document
WHERE tenant_id=#{caller.tenantId} AND owner_id=#{caller.userId} AND document_id=#{id}
FOR UPDATE

mapper.insert:
INSERT INTO knowledge_document_share (tenant_id,document_id,owner_id,recipient_id,active,revision,command_id,updated_at)
VALUES (#{caller.tenantId},#{receipt.documentId},#{caller.userId},#{receipt.recipientId},#{active},#{receipt.acceptedRevision},#{receipt.commandId},#{receipt.acceptedAt})
ON DUPLICATE KEY UPDATE active=#{active},revision=#{receipt.acceptedRevision},command_id=#{receipt.commandId},updated_at=#{receipt.acceptedAt}

mapper.select:
SELECT d.document_id,r.display_name,d.published_version AS version,d.published_generation AS index_generation,r.content_type,r.size_bytes

AND d.document_id=#{id}
AND d.document_id > #{after} ORDER BY d.document_id LIMIT #{limit}

SELECT d.document_id 
AND d.document_id IN #{id}
ORDER BY d.document_id LIMIT #{limit}
